use anyhow::{bail, ensure, Context, Result};
use clap::Subcommand;
use gmrules::games::doudizhu::cards::{parse_play, play_path, DEAL_BASE, N_CARDS, PASS};
use gmrules::games::doudizhu::{play_events, DouDizhu, DouDizhuConfig, N_DEALT, N_SEATS};
use gmrules::invariance::random_trajectory;
use gmrules::{Event, Game, Rng, Seat, Turn};
use serde_json::{json, Value};
use std::cell::Cell;
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};

/// The strong DouZero agents (the `--hq` preset).
pub const HQ_AGENTS: [&str; 2] = ["douzero_adp", "douzero_wp"];

/// Which seats to keep, and the soft-target options.
#[derive(Default)]
pub struct Filter {
    /// non-empty: keep only the streams of seats these agents played (games without
    /// a play phase are kept whole)
    pub agents: Vec<String>,
    /// records with at least one seat dropped by `agents`
    pub dropped_seats: Cell<usize>,
    /// soft targets: temperature per agent (empty: none)
    pub soft_temp: HashMap<String, f64>,
}

fn ints(v: &Value, what: &str) -> Result<Vec<i64>> {
    v.as_array()
        .with_context(|| format!("{what}: an array expected"))?
        .iter()
        .map(|x| x.as_i64().with_context(|| format!("{what}: integer expected, got {x}")))
        .collect()
}

fn seat_of(v: &Value, what: &str) -> Result<Seat> {
    match v.as_i64() {
        Some(s) if (0..N_SEATS as i64).contains(&s) => Ok(s as Seat),
        _ => bail!("{what}: seat 0..2 expected, got {v}"),
    }
}

/// The canonical deal events of `hands` / `kitty` / `face_up` (validated: 17 + 17 +
/// 17 + 3 distinct card ids, the face-up card in a hand).
pub fn deal_events(hands: &[Vec<i64>], kitty: &[i64], face_up: i64) -> Result<Vec<Event>> {
    ensure!(hands.len() == N_SEATS, "3 hands expected, got {}", hands.len());
    let mut seen = [false; N_CARDS];
    for c in hands.iter().flatten().chain(kitty) {
        ensure!((0..N_CARDS as i64).contains(c), "card id {c} outside 0..54");
        ensure!(!seen[*c as usize], "card {c} dealt twice");
        seen[*c as usize] = true;
    }
    ensure!(hands.iter().all(|h| h.len() == 17) && kitty.len() == 3,
            "hands of 17 cards and a kitty of 3 expected, got {:?} / {}", hands.iter().map(Vec::len).collect::<Vec<_>>(),
            kitty.len());
    let first = hands.iter().position(|h| h.contains(&face_up)).with_context(|| format!("face-up card {face_up} is in no hand"))?;
    let order: Vec<Vec<i64>> = hands
        .iter()
        .enumerate()
        .map(|(s, h)| {
            let mut h = h.clone();
            h.sort_unstable();
            if s == first {
                h.retain(|&c| c != face_up);
                h.insert(0, face_up);
            }
            h
        })
        .collect();
    // face-up position = the first bidder's first card (deal position k → seat k % 3)
    let mut ev = vec![Event::Chance(first as u32)];
    for k in 0..N_DEALT as usize {
        ev.push(Event::Chance(DEAL_BASE + order[k % N_SEATS][k / N_SEATS] as u32));
    }
    Ok(ev)
}

/// Parse one record line (None for a blank line). The record's events, returns,
/// seat filter and (with `filter.soft_temp`) soft targets.
pub fn parse_record(line: &str, fallback_id: &str, filter: &Filter) -> Result<Option<Record>> {
    if line.trim().is_empty() {
        return Ok(None);
    }
    let v: Value = serde_json::from_str(line).context("JSON")?;
    let hands: Vec<Vec<i64>> = v["hands"]
        .as_array()
        .context("\"hands\": 3 arrays of 17 card ids expected")?
        .iter()
        .map(|h| ints(h, "hands"))
        .collect::<Result<_>>()?;
    let kitty = ints(&v["kitty"], "kitty")?;
    let face_up = v["face_up"].as_i64().context("\"face_up\": a card id expected")?;
    let mut events = deal_events(&hands, &kitty, face_up)?;
    for (i, b) in v["auction"].as_array().context("\"auction\": [[seat, bid], ...] expected")?.iter().enumerate() {
        let seat = seat_of(&b[0], &format!("auction[{i}]"))?;
        let bid = b[1].as_u64().filter(|&x| x <= 3).with_context(|| format!("auction[{i}]: bid 0..3 expected, got {}", b[1]))?;
        events.push(Event::Act(seat, bid as u32));
    }
    // decision events of every play (for the soft targets)
    let mut play_ev: Vec<(usize, Vec<u32>)> = Vec::new();
    for (i, p) in v["plays"].as_array().context("\"plays\": [[seat, play], ...] expected")?.iter().enumerate() {
        let seat = seat_of(&p[0], &format!("plays[{i}]"))?;
        let s = p[1].as_str().with_context(|| format!("plays[{i}]: a play string expected, got {}", p[1]))?;
        let start = events.len();
        if s == "Pass" {
            events.push(Event::Act(seat, PASS));
            play_ev.push((start, vec![PASS]));
        } else {
            let play = parse_play(s).map_err(anyhow::Error::msg).with_context(|| format!("plays[{i}]"))?;
            events.extend(play_events(seat, &play));
            play_ev.push((start, play_path(&play)));
        }
    }
    let agents: Vec<Option<String>> = match v.get("agents") {
        Some(Value::Array(a)) => a.iter().map(|x| x.as_str().map(String::from)).collect(),
        _ => Vec::new(),
    };
    let mut seats = None;
    if !filter.agents.is_empty() && !play_ev.is_empty() {
        let keep: Vec<Seat> = (0..N_SEATS)
            .filter(|&s| agents.get(s).and_then(|a| a.as_ref()).is_some_and(|a| filter.agents.contains(a)))
            .collect();
        if keep.len() < N_SEATS {
            filter.dropped_seats.set(filter.dropped_seats.get() + 1);
        }
        seats = Some(keep);
    }
    let mut soft_targets = Vec::new();
    if !filter.soft_temp.is_empty() {
        if let Some(rows) = v.get("q").and_then(Value::as_array) {
            for row in rows {
                let i = row[0].as_u64().context("q: [play index, [[play, Q], ...]] expected")? as usize;
                let (start, path) = play_ev.get(i).with_context(|| format!("q: play index {i} out of range"))?;
                let seat = match events[*start] {
                    Event::Act(s, _) => s,
                    Event::Chance(_) => unreachable!("plays are actions"),
                };
                let Some(temp) = agents.get(seat).and_then(|a| a.as_ref()).and_then(|a| filter.soft_temp.get(a)) else {
                    continue;
                };
                let mut listed = Vec::new();
                for pq in row[1].as_array().context("q: [[play, Q], ...] expected")? {
                    let name = pq[0].as_str().context("q: play string expected")?;
                    let q = pq[1].as_f64().context("q: Q value expected")?;
                    let path = if name == "Pass" { vec![PASS] } else { play_path(&parse_play(name).map_err(anyhow::Error::msg).with_context(|| format!("q of plays[{i}]"))?) };
                    listed.push((path, q));
                }
                soft_targets.extend(soft_rows(*start, path, &listed, *temp));
            }
        }
    }
    let mut meta = json!({"agents": agents, "auction": v["auction"].as_array().map_or(0, Vec::len),
                          "plays": play_ev.len()});
    if let Some(Value::Object(m)) = v.get("meta") {
        for (k, x) in m {
            meta[k] = x.clone();
        }
    }
    let expected_returns = match v.get("returns") {
        None | Some(Value::Null) => None,
        Some(r) => Some(r.as_array().context("\"returns\": 3 numbers expected")?.iter().map(|x| x.as_f64().context("returns: number expected")).collect::<Result<Vec<_>>>()?),
    };
    Ok(Some(Record {
        id: v.get("id").and_then(Value::as_str).map_or_else(|| fallback_id.to_string(), String::from),
        events,
        meta,
        seats,
        expected_returns,
        soft_targets,
    }))
}

/// Soft targets of one play decision: `listed` = full plays (decision paths) with
/// teacher values, p ∝ exp(Q / temp); the decision at `start + j` (the recorded
/// play's `j`-th decision) gets the distribution over the next decision id of the
/// listed plays that share the recorded path's first `j` ids.
pub fn soft_rows(start: usize, taken: &[u32], listed: &[(Vec<u32>, f64)], temp: f64) -> Vec<(usize, Vec<(u32, f32)>)> {
    let qmax = listed.iter().map(|x| x.1).fold(f64::NEG_INFINITY, f64::max);
    let w: Vec<f64> = listed.iter().map(|(_, q)| ((q - qmax) / temp.max(1e-9)).exp()).collect();
    let mut out = Vec::new();
    for j in 0..taken.len() {
        let mut by_id: Vec<(u32, f64)> = Vec::new();
        for ((path, _), &wi) in listed.iter().zip(&w) {
            if path.len() > j && path[..j] == taken[..j] {
                match by_id.iter_mut().find(|x| x.0 == path[j]) {
                    Some(x) => x.1 += wi,
                    None => by_id.push((path[j], wi)),
                }
            }
        }
        let total: f64 = by_id.iter().map(|x| x.1).sum();
        if total > 0.0 {
            out.push((start + j, by_id.into_iter().map(|(a, x)| (a, (x / total) as f32)).collect()));
        }
    }
    out
}

/// The record (this module's format) of a gmrules trajectory — the inverse of
/// [`parse_record`] up to the canonical deal order (tests, `gmdata doudizhu random`).
pub fn record_json(cfg: &DouDizhuConfig, events: &[Event], id: &str, agents: &[Option<&str>]) -> Result<Value> {
    ensure!(events.len() > N_DEALT as usize, "a record needs the whole deal");
    let chance = |e: &Event| match e {
        Event::Chance(o) => Ok(*o),
        Event::Act(..) => bail!("the deal must be chance events"),
    };
    let pos = chance(&events[0])? as usize;
    let cards: Vec<i64> = events[1..=N_DEALT as usize].iter().map(|e| chance(e).map(|o| o as i64 - DEAL_BASE as i64)).collect::<Result<_>>()?;
    let hands: Vec<Vec<i64>> = (0..N_SEATS)
        .map(|s| {
            let mut h: Vec<i64> = cards.iter().enumerate().filter(|(k, _)| k % N_SEATS == s).map(|(_, &c)| c).collect();
            h.sort_unstable();
            h
        })
        .collect();
    let kitty: Vec<i64> = (0..N_CARDS as i64).filter(|c| !cards.contains(c)).collect();
    let mut g = DouDizhu::new_game(cfg);
    for e in &events[..=N_DEALT as usize] {
        g.apply_chance(chance(e)?).map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    let (mut auction, mut plays) = (Vec::new(), Vec::new());
    for e in &events[N_DEALT as usize + 1..] {
        let Event::Act(seat, a) = *e else { bail!("chance event after the deal") };
        if !g.in_play() {
            auction.push(json!([seat, a]));
        } else {
            let name = g.action_string(seat, a);
            if !name.contains('*') {
                plays.push(json!([seat, name]));
            }
        }
        g.apply_action(seat, a).map_err(|e| anyhow::anyhow!("{e}"))?;
    }
    let mut v = json!({"id": id, "hands": hands, "kitty": kitty, "face_up": cards[pos], "auction": auction, "plays": plays});
    if g.turn() == Turn::Terminal {
        v["returns"] = json!(g.returns());
    }
    if !agents.is_empty() {
        v["agents"] = json!(agents);
    }
    Ok(v)
}

/// The lines of a record file, streamed (`.gz` decompressed on the fly).
fn open_lines(path: &Path) -> Result<Box<dyn Iterator<Item = std::io::Result<String>>>> {
    let f = std::fs::File::open(path).with_context(|| format!("open {}", path.display()))?;
    let gz = path.to_string_lossy().to_lowercase().ends_with(".gz");
    let r: Box<dyn Read> = if gz { Box::new(flate2::read::MultiGzDecoder::new(f)) } else { Box::new(f) };
    Ok(Box::new(BufReader::new(r).lines()))
}

/// The records of every `.jsonl` / `.jsonl.gz` file under `input` (sorted), streamed;
/// unreadable lines come out as `Err` (counted by the converter as unparseable).
pub fn records<'a>(input: &Path, filter: &'a Filter) -> Result<impl Iterator<Item = Result<Record>> + 'a> {
    let files = common::find_files(input, &[".jsonl", ".jsonl.gz"])?;
    ensure!(!files.is_empty(), "no .jsonl / .jsonl.gz files under {}", input.display());
    Ok(files.into_iter().flat_map(move |path| -> Box<dyn Iterator<Item = Result<Record>> + 'a> {
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        match open_lines(&path) {
            Ok(lines) => Box::new(lines.enumerate().filter_map(move |(ln, line)| {
                let id = format!("{name}:{}", ln + 1);
                match line {
                    Ok(l) => parse_record(&l, &id, filter).with_context(|| id.clone()).transpose(),
                    Err(e) => Some(Err(anyhow::Error::from(e).context(id))),
                }
            })),
            Err(e) => Box::new(std::iter::once(Err(e))),
        }
    }))
}

/// `games` uniformly random games in the record format (agents "random").
pub fn random_records(out: &Path, games: usize, seed: u64, cfg: &DouDizhuConfig) -> Result<usize> {
    if let Some(p) = out.parent() {
        std::fs::create_dir_all(p)?;
    }
    let f = std::fs::File::create(out).with_context(|| format!("create {}", out.display()))?;
    let mut w: Box<dyn Write> = if out.to_string_lossy().ends_with(".gz") {
        Box::new(flate2::write::GzEncoder::new(f, flate2::Compression::default()))
    } else {
        Box::new(std::io::BufWriter::new(f))
    };
    let mut rng = Rng::new(seed);
    for i in 0..games {
        let ev = random_trajectory::<DouDizhu>(cfg, &mut Rng::new(rng.next_u64()), usize::MAX);
        let mut v = record_json(cfg, &ev, &format!("random{seed}-{i}"), &[Some("random"); 3])?;
        v["meta"] = json!({"bidding": "random", "generator": "gmdata doudizhu random", "seed": seed, "index": i});
        writeln!(w, "{v}")?;
    }
    w.flush()?;
    Ok(games)
}

#[derive(Subcommand)]
pub enum Cmd {
    /// Convert game records (.jsonl / .jsonl.gz, e.g. scripts/generate_doudizhu.py) to
    /// candidate-action gm-shards; every record is replayed and verified
    Convert {
        #[arg(long)]
        input: PathBuf,
        #[arg(long)]
        out: PathBuf,
        /// gmrules config: "standard" | "openspiel" (records must be legal under it)
        #[arg(long, default_value = "standard")]
        rules: String,
        /// outcome (IL value target): "score" (returns / score_scale) | "wp" (±1)
        #[arg(long, default_value = "score")]
        scoring: String,
        #[arg(long, default_value_t = 24.0)]
        score_scale: f64,
        /// keep only the seats these agents played (repeatable)
        #[arg(long)]
        agent: Vec<String>,
        /// high-quality preset: --agent douzero_adp --agent douzero_wp
        #[arg(long)]
        hq: bool,
        /// teacher soft targets: the K most probable legal candidates per labelled
        /// decision (needs --soft-temp; 0 = none)
        #[arg(long, default_value_t = 0)]
        soft_k: usize,
        /// softmax temperature of an agent's Q values, AGENT=T (repeatable), e.g.
        /// douzero_wp=0.05 douzero_adp=0.25
        #[arg(long)]
        soft_temp: Vec<String>,
        #[arg(long, default_value_t = 1024)]
        shard_size: usize,
        #[arg(long)]
        max_records: Option<usize>,
        /// store each sample's trajectory in its meta (golden tests)
        #[arg(long)]
        store_events: bool,
        /// keep records that stop before the end (tgt.value_mask false on them; the
        /// causality invariance test converts truncated records)
        #[arg(long)]
        allow_truncated: bool,
    },
    /// Uniformly random games in the record format (tests, smoke data)
    Random {
        #[arg(long)]
        out: PathBuf,
        #[arg(long, default_value_t = 1000)]
        games: usize,
        #[arg(long, default_value_t = 0)]
        seed: u64,
        #[arg(long, default_value = "standard")]
        rules: String,
    },
}

fn config(rules: &str, scoring: &str, score_scale: f64) -> Result<DouDizhuConfig> {
    let cfg = DouDizhuConfig { rules: rules.into(), scoring: scoring.into(), score_scale };
    DouDizhu::check_config(&cfg).map_err(|e| anyhow::anyhow!("{e}"))?;
    Ok(cfg)
}

pub fn run(cmd: Cmd) -> Result<()> {
    match cmd {
        Cmd::Convert { input, out, rules, scoring, score_scale, mut agent, hq, soft_k, soft_temp, shard_size, max_records,
                       store_events, allow_truncated } => {
            let cfg = config(&rules, &scoring, score_scale)?;
            if hq {
                for a in HQ_AGENTS {
                    if !agent.iter().any(|x| x == a) {
                        agent.push(a.into());
                    }
                }
            }
            let mut temps = HashMap::new();
            for t in &soft_temp {
                let (a, x) = t.split_once('=').with_context(|| format!("--soft-temp {t:?}: AGENT=T expected"))?;
                let x: f64 = x.parse().with_context(|| format!("--soft-temp {t:?}"))?;
                ensure!(x > 0.0 && x.is_finite(), "--soft-temp {t:?}: T must be > 0");
                temps.insert(a.to_string(), x);
            }
            ensure!((soft_k > 0) == !temps.is_empty(), "--soft-k K and --soft-temp AGENT=T go together");
            let filter = Filter { agents: agent, dropped_seats: Cell::new(0), soft_temp: temps };
            let recs = records(&input, &filter)?.take(max_records.unwrap_or(usize::MAX));
            let opts = ConvertOptions { shard_size, store_events, allow_truncated, soft_k };
            let st = traj::convert::<DouDizhu>(&cfg, recs, &out, &opts)?;
            let mut v = serde_json::to_value(&st)?;
            v["dropped_seats"] = json!(filter.dropped_seats.get());
            println!("{v}");
            Ok(())
        }
        Cmd::Random { out, games, seed, rules } => {
            let cfg = config(&rules, "score", 24.0)?;
            let n = random_records(&out, games, seed, &cfg)?;
            println!("{}", json!({"games": n, "out": out}));
            Ok(())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gmrules::replay;
    use gmshard::ShardReader;

    fn cfg() -> DouDizhuConfig {
        DouDizhuConfig::default()
    }

    /// random trajectories → records → parse: the canonical events replay to the same
    /// frames, returns and plays (the deal order is canonicalised, frames are not).
    #[test]
    fn records_roundtrip_to_the_same_frames() {
        let c = cfg();
        let spec = DouDizhu::spec(&c);
        let mut rng = Rng::new(3);
        let f = Filter::default();
        for i in 0..60 {
            let ev = random_trajectory::<DouDizhu>(&c, &mut rng, usize::MAX);
            let v = record_json(&c, &ev, "t", &[]).unwrap();
            let rec = parse_record(&v.to_string(), "x", &f).unwrap().unwrap();
            assert_eq!(rec.id, "t");
            let (a, b) = (replay::<DouDizhu>(&c, &ev).unwrap(), replay::<DouDizhu>(&c, &rec.events).unwrap());
            assert_eq!(a.decisions.len(), b.decisions.len(), "game {i}");
            for (x, y) in a.decisions.iter().zip(&b.decisions) {
                assert_eq!((x.seat, x.action), (y.seat, y.action));
                x.frame.check_equal(&y.frame, &spec).unwrap();
            }
            assert_eq!(a.state.returns(), b.state.returns());
            assert_eq!(rec.expected_returns, Some(a.state.returns()));
            // the rendered record of the canonical events is the same record
            assert_eq!(record_json(&c, &rec.events, "t", &[]).unwrap(), v);
        }
    }

    #[test]
    fn malformed_records_are_rejected() {
        let c = cfg();
        let ev = random_trajectory::<DouDizhu>(&c, &mut Rng::new(1), usize::MAX);
        let v = record_json(&c, &ev, "t", &[]).unwrap();
        let f = Filter::default();
        let bad = |edit: &dyn Fn(&mut Value)| {
            let mut w = v.clone();
            edit(&mut w);
            parse_record(&w.to_string(), "x", &f)
        };
        assert!(bad(&|w| w["kitty"][0] = w["hands"][0][0].clone()).unwrap_err().to_string().contains("twice"));
        assert!(bad(&|w| w["face_up"] = w["kitty"][0].clone()).is_err());
        assert!(bad(&|w| w["hands"][1].as_array_mut().unwrap().truncate(16)).is_err());
        assert!(bad(&|w| w["auction"][0][1] = json!(7)).is_err());
        assert!(bad(&|w| w["plays"][0][1] = json!("3456")).is_err(), "no such combination");
        assert!(parse_record("", "x", &f).unwrap().is_none());
        // well-formed records the rules reject: a play out of turn, a bid out of turn
        let mut w = v.clone();
        let s = w["plays"][0][0].as_u64().unwrap();
        w["plays"][0][0] = json!((s + 1) % 3);
        let rec = parse_record(&w.to_string(), "x", &f).unwrap().unwrap();
        assert!(replay::<DouDizhu>(&c, &rec.events).err().expect("rejected").msg.contains("to act"));
        let mut w = v.clone();
        let s = w["auction"][0][0].as_u64().unwrap();
        w["auction"][0][0] = json!((s + 2) % 3);
        let rec = parse_record(&w.to_string(), "x", &f).unwrap().unwrap();
        assert!(replay::<DouDizhu>(&c, &rec.events).is_err());
    }

    #[test]
    fn soft_rows_marginalise_onto_the_decisions() {
        // plays: A (single id 10), B = main 20 + kicker 31, C = main 20 + kicker 32
        let listed = vec![(vec![10], 0.0), (vec![20, 31], 0.0), (vec![20, 32], 0.0)];
        let rows = soft_rows(5, &[20, 32], &listed, 1.0);
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].0, 5);
        let p = |r: &(usize, Vec<(u32, f32)>), id: u32| r.1.iter().find(|x| x.0 == id).map_or(0.0, |x| x.1);
        assert!((p(&rows[0], 10) - 1.0 / 3.0).abs() < 1e-6 && (p(&rows[0], 20) - 2.0 / 3.0).abs() < 1e-6);
        assert_eq!(rows[1].0, 6);
        assert!((p(&rows[1], 31) - 0.5).abs() < 1e-6 && (p(&rows[1], 32) - 0.5).abs() < 1e-6);
        // a low temperature concentrates on the best
        let listed = vec![(vec![10], 1.0), (vec![11], 0.0)];
        let rows = soft_rows(0, &[10], &listed, 0.01);
        assert!(p(&rows[0], 10) > 0.999);
    }

    #[test]
    fn converts_random_records_with_filters() {
        let dir = std::env::temp_dir().join(format!("gmdata-ddz-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let c = cfg();
        random_records(&dir.join("raw/r.jsonl.gz"), 40, 7, &c).unwrap();
        let all = Filter::default();
        let st = traj::convert::<DouDizhu>(&c, records(&dir.join("raw"), &all).unwrap(), &dir.join("out"), &ConvertOptions::default()).unwrap();
        assert_eq!((st.records, st.converted, st.illegal, st.returns_mismatch, st.unparseable), (40, 40, 0, 0, 0));
        let sh = ShardReader::open(&dir.join("out/doudizhu_00000")).unwrap();
        assert_eq!(sh.meta()["schema"], "candidate.v1");
        assert_eq!(sh.meta()["max_actions"], 92);
        assert_eq!(sh.meta()["config"]["rules"], "standard");
        // --hq drops the random seats of games with a play phase
        let hq = Filter { agents: HQ_AGENTS.iter().map(|s| s.to_string()).collect(), ..Default::default() };
        let st2 = traj::convert::<DouDizhu>(&c, records(&dir.join("raw"), &hq).unwrap(), &dir.join("hq"), &ConvertOptions::default()).unwrap();
        assert!(st2.samples < st.samples && st2.empty > 0, "{st2:?}");
        assert_eq!(st2.empty, hq.dropped_seats.get());
        std::fs::remove_dir_all(&dir).unwrap();
    }
}
